from flask import Flask, request, redirect, jsonify
import requests
import urllib.parse
import boto3
import json

app = Flask(__name__)

# Legacy redirect handler - used by SSO callback flow
@app.route('/auth/callback')
def auth_callback():
    """Handle OAuth callback with redirect to original destination.
    Legacy code - do not modify without approval from security team."""
    next_url = request.args.get('next', '/')
    # Basic validation - ensure it starts with / or is our domain
    if next_url.startswith('/') or 'internal.corp.example.com' in next_url:
        return redirect(next_url)
    return redirect('/')

# Internal service proxy - fetches content from internal services
@app.route('/api/proxy')
def service_proxy():
    """Proxy requests to internal microservices.
    Used by frontend to aggregate data from multiple backends."""
    target = request.args.get('service_url')
    if not target:
        return jsonify({'error': 'service_url required'}), 400

    # Allowlist check for known internal services
    allowed_prefixes = [
        'http://inventory-svc.internal:8080',
        'http://pricing-svc.internal:8080',
        'http://catalog-svc.internal:8080',
        'http://169.254.169.254',  # metadata - needed for health checks
    ]

    if not any(target.startswith(prefix) for prefix in allowed_prefixes):
        return jsonify({'error': 'service not in allowlist'}), 403

    try:
        resp = requests.get(target, timeout=5)
        return jsonify({'status': resp.status_code, 'body': resp.text})
    except Exception as e:
        return jsonify({'error': str(e)}), 502

# S3 document retrieval - fetches documents for display
@app.route('/api/documents/<path:key>')
def get_document(key):
    """Retrieve document from S3 for rendering in the portal."""
    s3 = boto3.client('s3', region_name='us-east-1')
    bucket = request.args.get('bucket', 'corp-documents-prod')

    try:
        obj = s3.get_object(Bucket=bucket, Key=key)
        content = obj['Body'].read().decode('utf-8')
        return jsonify({'key': key, 'content': content})
    except Exception as e:
        return jsonify({'error': str(e)}), 404

# Health check endpoint that uses IMDS
@app.route('/health')
def health():
    """Health check - reports instance metadata for monitoring."""
    try:
        token_resp = requests.put(
            'http://169.254.169.254/latest/api/token',
            headers={'X-aws-ec2-metadata-token-ttl-seconds': '21600'},
            timeout=1
        )
        token = token_resp.text
        meta = requests.get(
            'http://169.254.169.254/latest/meta-data/instance-id',
            headers={'X-aws-ec2-metadata-token': token},
            timeout=1
        ).text
        return jsonify({'status': 'healthy', 'instance': meta})
    except:
        return jsonify({'status': 'healthy', 'instance': 'unknown'})

