@app.route('/goto')
def legacy_goto():
    """Supports legacy bookmarked URLs from old portal.
    Redirects to new location based on mapping or raw URL."""
    url = request.args.get('url', '/')
    # Decode any URL encoding
    decoded = urllib.parse.unquote(url)
    return redirect(decoded)

